  "knowledge": "Cross-Border Risk Factor (CBRF)",
  "description": "Evaluates risk associated with cross-border data transfers.",
  "definition": "CBRF = \\text{RES} \\times \\begin{cases} 2 & \\text{if OrigNation \\neq DestNation} \\\\ 1 & \\text{otherwise} \\end{cases}"
}

